namespace ContosoUniversity.Tests
{
    public class SchoolContextTests : IDisposable
    {
        private readonly SchoolContext _context;

        public SchoolContextTests()
        {
            _context = TestDbContextFactory.Create();
        }

        public void Dispose()
        {
            _context.Dispose();
        }

        [Fact]
        public void Context_CanAddAndRetrieveStudent()
        {
            // Arrange
            var student = new Student { FirstMidName = "Test", LastName = "User", EnrollmentDate = new DateTime(2023, 1, 1) };

            // Act
            _context.Students.Add(student);
            _context.SaveChanges();

            // Assert
            var retrieved = _context.Students.First();
            Assert.Equal("Test", retrieved.FirstMidName);
            Assert.Equal("User", retrieved.LastName);
        }

        [Fact]
        public void Context_CanAddAndRetrieveCourse()
        {
            // Arrange
            var dept = new Department { Name = "Test", Budget = 100, StartDate = DateTime.Now };
            _context.Departments.Add(dept);
            _context.SaveChanges();

            var course = new Course { CourseID = 5000, Title = "TestCourse", Credits = 3, DepartmentID = dept.DepartmentID };

            // Act
            _context.Courses.Add(course);
            _context.SaveChanges();

            // Assert
            var retrieved = _context.Courses.Find(5000);
            Assert.NotNull(retrieved);
            Assert.Equal("TestCourse", retrieved.Title);
        }

        [Fact]
        public void Context_CourseAssignment_CompositeKey()
        {
            // Arrange
            var instructor = new Instructor { FirstMidName = "I", LastName = "Test", HireDate = DateTime.Now };
            _context.Instructors.Add(instructor);
            var dept = new Department { Name = "D", Budget = 100, StartDate = DateTime.Now };
            _context.Departments.Add(dept);
            _context.SaveChanges();

            var course = new Course { CourseID = 6000, Title = "C", Credits = 3, DepartmentID = dept.DepartmentID };
            _context.Courses.Add(course);
            _context.SaveChanges();

            // Act
            var assignment = new CourseAssignment { CourseID = 6000, InstructorID = instructor.ID };
            _context.CourseAssignments.Add(assignment);
            _context.SaveChanges();

            // Assert
            var retrieved = _context.CourseAssignments.Find(6000, instructor.ID);
            Assert.NotNull(retrieved);
        }

        [Fact]
        public void Context_InstructorOfficeAssignment_OneToOne()
        {
            // Arrange
            var instructor = new Instructor
            {
                FirstMidName = "Office",
                LastName = "Instructor",
                HireDate = DateTime.Now,
                OfficeAssignment = new OfficeAssignment { Location = "Room A" }
            };

            // Act
            _context.Instructors.Add(instructor);
            _context.SaveChanges();

            // Assert
            var retrieved = _context.Instructors
                .Include(i => i.OfficeAssignment)
                .First(i => i.LastName == "Instructor");
            Assert.NotNull(retrieved.OfficeAssignment);
            Assert.Equal("Room A", retrieved.OfficeAssignment.Location);
        }

        [Fact]
        public void Context_Enrollment_LinksStudentAndCourse()
        {
            // Arrange
            var student = new Student { FirstMidName = "S", LastName = "T", EnrollmentDate = DateTime.Now };
            _context.Students.Add(student);
            var dept = new Department { Name = "D", Budget = 100, StartDate = DateTime.Now };
            _context.Departments.Add(dept);
            _context.SaveChanges();

            var course = new Course { CourseID = 7000, Title = "Link", Credits = 2, DepartmentID = dept.DepartmentID };
            _context.Courses.Add(course);
            _context.SaveChanges();

            var enrollment = new Enrollment { StudentID = student.ID, CourseID = 7000, Grade = Grade.B };
            _context.Enrollments.Add(enrollment);
            _context.SaveChanges();

            // Assert
            var retrieved = _context.Enrollments
                .Include(e => e.Student)
                .Include(e => e.Course)
                .First();
            Assert.Equal(student.ID, retrieved.StudentID);
            Assert.Equal(7000, retrieved.CourseID);
            Assert.Equal(Grade.B, retrieved.Grade);
        }
    }

    public class DbInitializerTests : IDisposable
    {
        private readonly SchoolContext _context;

        public DbInitializerTests()
        {
            _context = TestDbContextFactory.Create();
        }

        public void Dispose()
        {
            _context.Dispose();
        }

        [Fact]
        public void Initialize_SeedsDatabase()
        {
            // Act
            DbInitializer.Initialize(_context);

            // Assert
            Assert.True(_context.Students.Any());
            Assert.True(_context.Instructors.Any());
            Assert.True(_context.Departments.Any());
            Assert.True(_context.Courses.Any());
            Assert.True(_context.Enrollments.Any());
        }

        [Fact]
        public void Initialize_CalledTwice_DoesNotDuplicate()
        {
            // Act
            DbInitializer.Initialize(_context);
            var countAfterFirst = _context.Students.Count();
            DbInitializer.Initialize(_context);
            var countAfterSecond = _context.Students.Count();

            // Assert
            Assert.Equal(countAfterFirst, countAfterSecond);
        }
    }
}
