using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.ViewFeatures;
using Microsoft.EntityFrameworkCore;
using Xunit;

namespace ContosoUniversity.Tests.Controllers
{
    public class StudentsControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly StudentsController _controller;

        public StudentsControllerTests()
        {
            _context = TestDbContextFactory.Create();
            _controller = new StudentsController(_context);
            // Setup TempData for controller
            _controller.TempData = new TempDataDictionary(
                new DefaultHttpContext(), 
                new SessionStateTempDataProvider(new SessionStateTempDataSerializer()));
        }

        public void Dispose()
        {
            _controller.Dispose();
            _context.Dispose();
        }

        private void SeedStudents()
        {
            _context.Students.AddRange(
                new Student { FirstMidName = "Alice", LastName = "Anderson", EnrollmentDate = new DateTime(2020, 9, 1) },
                new Student { FirstMidName = "Bob", LastName = "Baker", EnrollmentDate = new DateTime(2021, 1, 15) },
                new Student { FirstMidName = "Charlie", LastName = "Clark", EnrollmentDate = new DateTime(2019, 6, 1) }
            );
            _context.SaveChanges();
        }

        #region Index

        [Fact]
        public void Index_NoParams_ReturnsViewWithStudentsOrderedByLastName()
        {
            // Arrange
            SeedStudents();

            // Act
            var result = _controller.Index(null, null, null, null) as ViewResult;

            // Assert
            Assert.NotNull(result);
            var model = Assert.IsType<PaginatedList<Student>>(result.Model);
            Assert.Equal(3, model.Count);
            Assert.Equal("Anderson", model[0].LastName);
            Assert.Equal("Baker", model[1].LastName);
            Assert.Equal("Clark", model[2].LastName);
        }

        [Fact]
        public void Index_NameDescSort_ReturnsDescendingOrder()
        {
            // Arrange
            SeedStudents();

            // Act
            var result = _controller.Index("name_desc", null, null, null) as ViewResult;

            // Assert
            var model = Assert.IsType<PaginatedList<Student>>(result.Model);
            Assert.Equal("Clark", model[0].LastName);
            Assert.Equal("Baker", model[1].LastName);
            Assert.Equal("Anderson", model[2].LastName);
        }

        [Fact]
        public void Index_DateSort_ReturnsOrderedByEnrollmentDateAsc()
        {
            // Arrange
            SeedStudents();

            // Act
            var result = _controller.Index("Date", null, null, null) as ViewResult;

            // Assert
            var model = Assert.IsType<PaginatedList<Student>>(result.Model);
            Assert.Equal("Clark", model[0].LastName); // 2019
            Assert.Equal("Anderson", model[1].LastName); // 2020
            Assert.Equal("Baker", model[2].LastName); // 2021
        }

        [Fact]
        public void Index_DateDescSort_ReturnsOrderedByEnrollmentDateDesc()
        {
            // Arrange
            SeedStudents();

            // Act
            var result = _controller.Index("date_desc", null, null, null) as ViewResult;

            // Assert
            var model = Assert.IsType<PaginatedList<Student>>(result.Model);
            Assert.Equal("Baker", model[0].LastName); // 2021
        }

        [Fact]
        public void Index_SearchString_FiltersStudents()
        {
            // Arrange
            SeedStudents();

            // Act
            var result = _controller.Index(null, null, "Alice", null) as ViewResult;

            // Assert
            var model = Assert.IsType<PaginatedList<Student>>(result.Model);
            Assert.Single(model);
            Assert.Equal("Alice", model[0].FirstMidName);
        }

        [Fact]
        public void Index_SearchByLastName_FiltersCorrectly()
        {
            // Arrange
            SeedStudents();

            // Act
            var result = _controller.Index(null, null, "Baker", null) as ViewResult;

            // Assert
            var model = Assert.IsType<PaginatedList<Student>>(result.Model);
            Assert.Single(model);
            Assert.Equal("Bob", model[0].FirstMidName);
        }

        [Fact]
        public void Index_SearchStringResetsPage()
        {
            // Arrange
            SeedStudents();

            // Act - when searchString is provided, page is reset to 1
            var result = _controller.Index(null, null, "A", 5) as ViewResult;

            // Assert - should still return results (page forced to 1)
            var model = Assert.IsType<PaginatedList<Student>>(result.Model);
            Assert.NotEmpty(model);
        }

        [Fact]
        public void Index_CurrentFilter_UsedWhenSearchStringNull()
        {
            // Arrange
            SeedStudents();

            // Act
            var result = _controller.Index(null, "Anderson", null, null) as ViewResult;

            // Assert
            var model = Assert.IsType<PaginatedList<Student>>(result.Model);
            Assert.Single(model);
        }

        #endregion

        #region Details

        [Fact]
        public void Details_NullId_ReturnsBadRequest()
        {
            // Act
            var result = _controller.Details(null);

            // Assert
            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Details_ValidId_ReturnsStudentWithEnrollments()
        {
            // Arrange
            SeedStudents();
            var student = _context.Students.First();
            var course = new Course { CourseID = 100, Title = "Test", Credits = 3, DepartmentID = 0 };
            _context.Courses.Add(course);
            _context.Enrollments.Add(new Enrollment { StudentID = student.ID, CourseID = 100, Grade = Grade.A });
            _context.SaveChanges();

            // Act
            var result = _controller.Details(student.ID) as ViewResult;

            // Assert
            Assert.NotNull(result);
            var model = Assert.IsType<Student>(result.Model);
            Assert.Equal(student.ID, model.ID);
            Assert.NotNull(model.Enrollments);
        }

        #endregion

        #region Create

        [Fact]
        public void Create_Get_ReturnsViewWithStudentDefaultDate()
        {
            // Act
            var result = _controller.Create() as ViewResult;

            // Assert
            Assert.NotNull(result);
            var model = Assert.IsType<Student>(result.Model);
            Assert.Equal(DateTime.Today, model.EnrollmentDate);
        }

        [Fact]
        public void Create_Post_ValidStudent_RedirectsToIndex()
        {
            // Arrange
            var student = new Student
            {
                FirstMidName = "New",
                LastName = "Student",
                EnrollmentDate = new DateTime(2023, 9, 1)
            };

            // Act
            var result = _controller.Create(student);

            // Assert
            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
            Assert.Single(_context.Students);
        }

        [Fact]
        public void Create_Post_InvalidEnrollmentDate_ReturnsViewWithError()
        {
            // Arrange
            var student = new Student
            {
                FirstMidName = "New",
                LastName = "Student",
                EnrollmentDate = DateTime.MinValue
            };

            // Act
            var result = _controller.Create(student) as ViewResult;

            // Assert
            Assert.NotNull(result);
            Assert.False(_controller.ModelState.IsValid);
            Assert.Empty(_context.Students);
        }

        [Fact]
        public void Create_Post_DateBelow1753_ReturnsViewWithError()
        {
            // Arrange
            var student = new Student
            {
                FirstMidName = "Old",
                LastName = "Timer",
                EnrollmentDate = new DateTime(1600, 1, 1)
            };

            // Act
            var result = _controller.Create(student) as ViewResult;

            // Assert
            Assert.NotNull(result);
            Assert.False(_controller.ModelState.IsValid);
        }

        [Fact]
        public void Create_Post_ModelStateInvalid_ReturnsView()
        {
            // Arrange
            var student = new Student
            {
                FirstMidName = "Test",
                LastName = "User",
                EnrollmentDate = new DateTime(2023, 1, 1)
            };
            _controller.ModelState.AddModelError("LastName", "Required");

            // Act
            var result = _controller.Create(student) as ViewResult;

            // Assert
            Assert.NotNull(result);
            Assert.Equal(student, result.Model);
        }

        #endregion

        #region Edit

        [Fact]
        public void Edit_Get_NullId_ReturnsBadRequest()
        {
            // Act
            var result = _controller.Edit((int?)null);

            // Assert
            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Edit_Get_NotFound_ReturnsNotFound()
        {
            // Act
            var result = _controller.Edit(999);

            // Assert
            Assert.IsType<NotFoundResult>(result);
        }

        [Fact]
        public void Edit_Get_ValidId_ReturnsViewWithStudent()
        {
            // Arrange
            SeedStudents();
            var student = _context.Students.First();

            // Act
            var result = _controller.Edit(student.ID) as ViewResult;

            // Assert
            Assert.NotNull(result);
            var model = Assert.IsType<Student>(result.Model);
            Assert.Equal(student.ID, model.ID);
        }

        [Fact]
        public void Edit_Post_ValidStudent_RedirectsToIndex()
        {
            // Arrange
            SeedStudents();
            var student = _context.Students.First();
            _context.Entry(student).State = EntityState.Detached;

            var updatedStudent = new Student
            {
                ID = student.ID,
                FirstMidName = "Updated",
                LastName = "Name",
                EnrollmentDate = new DateTime(2023, 5, 1)
            };

            // Act
            var result = _controller.Edit(updatedStudent);

            // Assert
            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
        }

        [Fact]
        public void Edit_Post_InvalidDate_ReturnsViewWithError()
        {
            // Arrange
            SeedStudents();
            var student = _context.Students.First();
            _context.Entry(student).State = EntityState.Detached;

            var updatedStudent = new Student
            {
                ID = student.ID,
                FirstMidName = "Updated",
                LastName = "Name",
                EnrollmentDate = DateTime.MinValue
            };

            // Act
            var result = _controller.Edit(updatedStudent) as ViewResult;

            // Assert
            Assert.NotNull(result);
            Assert.False(_controller.ModelState.IsValid);
        }

        #endregion

        #region Delete

        [Fact]
        public void Delete_Get_NullId_ReturnsBadRequest()
        {
            // Act
            var result = _controller.Delete(null);

            // Assert
            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Delete_Get_NotFound_ReturnsNotFound()
        {
            // Act
            var result = _controller.Delete(999);

            // Assert
            Assert.IsType<NotFoundResult>(result);
        }

        [Fact]
        public void Delete_Get_ValidId_ReturnsViewWithStudent()
        {
            // Arrange
            SeedStudents();
            var student = _context.Students.First();

            // Act
            var result = _controller.Delete(student.ID) as ViewResult;

            // Assert
            Assert.NotNull(result);
            var model = Assert.IsType<Student>(result.Model);
            Assert.Equal(student.ID, model.ID);
        }

        [Fact]
        public void DeleteConfirmed_RemovesStudentAndRedirects()
        {
            // Arrange
            SeedStudents();
            var student = _context.Students.First();

            // Act
            var result = _controller.DeleteConfirmed(student.ID);

            // Assert
            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
            Assert.Null(_context.Students.Find(student.ID));
        }

        #endregion
    }
}

