using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Models.SchoolViewModels;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.ViewFeatures;
using Microsoft.EntityFrameworkCore;
using Xunit;

namespace ContosoUniversity.Tests.Controllers
{
    public class InstructorsControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly InstructorsController _controller;

        public InstructorsControllerTests()
        {
            _context = TestDbContextFactory.Create();
            _controller = new InstructorsController(_context);
            _controller.TempData = new TempDataDictionary(
                new DefaultHttpContext(),
                new SessionStateTempDataProvider(new SessionStateTempDataSerializer()));
        }

        public void Dispose()
        {
            _controller.Dispose();
            _context.Dispose();
        }

        private void SeedInstructorsWithCourses()
        {
            var dept = new Department { Name = "Engineering", Budget = 100000, StartDate = new DateTime(2010, 1, 1) };
            _context.Departments.Add(dept);
            _context.SaveChanges();

            var instructor1 = new Instructor
            {
                FirstMidName = "Kim",
                LastName = "Abercrombie",
                HireDate = new DateTime(2000, 3, 11),
                OfficeAssignment = new OfficeAssignment { Location = "Room 101" },
                CourseAssignments = new List<CourseAssignment>()
            };
            var instructor2 = new Instructor
            {
                FirstMidName = "Fadi",
                LastName = "Fakhouri",
                HireDate = new DateTime(2002, 7, 6),
                CourseAssignments = new List<CourseAssignment>()
            };
            _context.Instructors.AddRange(instructor1, instructor2);
            _context.SaveChanges();

            var course = new Course { CourseID = 1050, Title = "Chemistry", Credits = 3, DepartmentID = dept.DepartmentID };
            _context.Courses.Add(course);
            _context.SaveChanges();

            _context.CourseAssignments.Add(new CourseAssignment { InstructorID = instructor1.ID, CourseID = 1050 });
            _context.SaveChanges();
        }

        #region Index

        [Fact]
        public void Index_NoParams_ReturnsAllInstructors()
        {
            // Arrange
            SeedInstructorsWithCourses();

            // Act
            var result = _controller.Index(null, null) as ViewResult;

            // Assert
            Assert.NotNull(result);
            var model = Assert.IsType<InstructorIndexData>(result.Model);
            Assert.Equal(2, model.Instructors.Count());
        }

        [Fact]
        public void Index_WithInstructorId_PopulatesCourses()
        {
            // Arrange
            SeedInstructorsWithCourses();
            var instructor = _context.Instructors.First(i => i.LastName == "Abercrombie");

            // Act
            var result = _controller.Index(instructor.ID, null) as ViewResult;

            // Assert
            var model = Assert.IsType<InstructorIndexData>(result.Model);
            Assert.NotNull(model.Courses);
            Assert.Single(model.Courses);
            Assert.Equal("Chemistry", model.Courses.First().Title);
        }

        [Fact]
        public void Index_WithCourseId_PopulatesEnrollments()
        {
            // Arrange
            SeedInstructorsWithCourses();
            var instructor = _context.Instructors.First(i => i.LastName == "Abercrombie");

            // Add an enrollment
            var student = new Student { FirstMidName = "Test", LastName = "Student", EnrollmentDate = DateTime.Now };
            _context.Students.Add(student);
            _context.SaveChanges();
            _context.Enrollments.Add(new Enrollment { StudentID = student.ID, CourseID = 1050, Grade = Grade.A });
            _context.SaveChanges();

            // Act
            var result = _controller.Index(instructor.ID, 1050) as ViewResult;

            // Assert
            var model = Assert.IsType<InstructorIndexData>(result.Model);
            Assert.NotNull(model.Enrollments);
            Assert.Single(model.Enrollments);
        }

        #endregion

        #region Details

        [Fact]
        public void Details_NullId_ReturnsBadRequest()
        {
            var result = _controller.Details(null);
            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Details_NotFound_ReturnsNotFound()
        {
            var result = _controller.Details(999);
            Assert.IsType<NotFoundResult>(result);
        }

        [Fact]
        public void Details_ValidId_ReturnsInstructor()
        {
            // Arrange
            SeedInstructorsWithCourses();
            var instructor = _context.Instructors.First();

            // Act
            var result = _controller.Details(instructor.ID) as ViewResult;

            // Assert
            Assert.NotNull(result);
            var model = Assert.IsType<Instructor>(result.Model);
            Assert.Equal(instructor.ID, model.ID);
        }

        #endregion

        #region Create

        [Fact]
        public void Create_Get_ReturnsViewWithInstructorAndCourses()
        {
            // Arrange
            SeedInstructorsWithCourses();

            // Act
            var result = _controller.Create() as ViewResult;

            // Assert
            Assert.NotNull(result);
            var model = Assert.IsType<Instructor>(result.Model);
            Assert.NotNull(model.CourseAssignments);
        }

        [Fact]
        public void Create_Post_ValidInstructor_RedirectsToIndex()
        {
            // Arrange
            SeedInstructorsWithCourses();
            var instructor = new Instructor
            {
                FirstMidName = "New",
                LastName = "Instructor",
                HireDate = new DateTime(2023, 1, 1),
                CourseAssignments = new List<CourseAssignment>()
            };

            // Act
            var result = _controller.Create(instructor, null);

            // Assert
            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
        }

        [Fact]
        public void Create_Post_WithSelectedCourses_AssignsCourses()
        {
            // Arrange
            SeedInstructorsWithCourses();
            var instructor = new Instructor
            {
                FirstMidName = "New",
                LastName = "WithCourse",
                HireDate = new DateTime(2023, 1, 1)
            };
            var selectedCourses = new[] { "1050" };

            // Act
            var result = _controller.Create(instructor, selectedCourses);

            // Assert
            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
            var saved = _context.Instructors
                .Include(i => i.CourseAssignments)
                .First(i => i.LastName == "WithCourse");
            Assert.Single(saved.CourseAssignments);
        }

        [Fact]
        public void Create_Post_InvalidModelState_ReturnsView()
        {
            // Arrange
            SeedInstructorsWithCourses();
            var instructor = new Instructor
            {
                FirstMidName = "Test",
                LastName = "Invalid",
                HireDate = new DateTime(2023, 1, 1),
                CourseAssignments = new List<CourseAssignment>()
            };
            _controller.ModelState.AddModelError("LastName", "Error");

            // Act
            var result = _controller.Create(instructor, null) as ViewResult;

            // Assert
            Assert.NotNull(result);
        }

        #endregion

        #region Delete

        [Fact]
        public void Delete_Get_NullId_ReturnsBadRequest()
        {
            var result = _controller.Delete(null);
            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Delete_Get_NotFound_ReturnsNotFound()
        {
            var result = _controller.Delete(999);
            Assert.IsType<NotFoundResult>(result);
        }

        [Fact]
        public void Delete_Get_ValidId_ReturnsView()
        {
            // Arrange
            SeedInstructorsWithCourses();
            var instructor = _context.Instructors.First();

            // Act
            var result = _controller.Delete(instructor.ID) as ViewResult;

            // Assert
            Assert.NotNull(result);
            var model = Assert.IsType<Instructor>(result.Model);
            Assert.Equal(instructor.ID, model.ID);
        }

        [Fact]
        public void DeleteConfirmed_RemovesInstructorAndClearsDepartmentFK()
        {
            // Arrange
            SeedInstructorsWithCourses();
            var instructor = _context.Instructors.First(i => i.LastName == "Abercrombie");

            // Assign this instructor as department admin
            var dept = _context.Departments.First();
            dept.InstructorID = instructor.ID;
            _context.SaveChanges();

            // Act
            var result = _controller.DeleteConfirmed(instructor.ID);

            // Assert
            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
            Assert.Null(_context.Instructors.Find(instructor.ID));
            // Department's InstructorID should be cleared
            var updatedDept = _context.Departments.Find(dept.DepartmentID);
            Assert.Null(updatedDept.InstructorID);
        }

        #endregion
    }
}

