using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.ViewFeatures;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Logging;
using Moq;
using Xunit;

namespace ContosoUniversity.Tests.Controllers
{
    /// <summary>
    /// Additional tests for CoursesController edge cases to improve coverage.
    /// </summary>
    public class CoursesControllerEdgeCaseTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly CoursesController _controller;
        private readonly Mock<IWebHostEnvironment> _mockEnv;
        private readonly Mock<ILogger<CoursesController>> _mockLogger;
        private readonly string _tempDir;

        public CoursesControllerEdgeCaseTests()
        {
            _context = TestDbContextFactory.Create();
            _tempDir = Path.Combine(Path.GetTempPath(), Guid.NewGuid().ToString());
            Directory.CreateDirectory(_tempDir);
            _mockEnv = new Mock<IWebHostEnvironment>();
            _mockEnv.Setup(e => e.WebRootPath).Returns(_tempDir);
            _mockEnv.Setup(e => e.ContentRootPath).Returns(_tempDir);
            _mockLogger = new Mock<ILogger<CoursesController>>();
            _controller = new CoursesController(_context, _mockEnv.Object, _mockLogger.Object);
            _controller.TempData = new TempDataDictionary(
                new DefaultHttpContext(),
                Mock.Of<ITempDataProvider>());
        }

        public void Dispose()
        {
            _controller.Dispose();
            _context.Dispose();
            if (Directory.Exists(_tempDir))
                Directory.Delete(_tempDir, true);
        }

        private Department SeedDepartment()
        {
            var dept = new Department { Name = "Test", Budget = 100000, StartDate = new DateTime(2020, 1, 1) };
            _context.Departments.Add(dept);
            _context.SaveChanges();
            return dept;
        }

        [Fact]
        public void Edit_Post_WithValidImage_UpdatesImagePathAndRedirects()
        {
            // Arrange
            var dept = SeedDepartment();
            var course = new Course { CourseID = 3001, Title = "Edit Image Test", Credits = 3, DepartmentID = dept.DepartmentID };
            _context.Courses.Add(course);
            _context.SaveChanges();
            _context.Entry(course).State = EntityState.Detached;

            var updated = new Course { CourseID = 3001, Title = "Edit Image Test", Credits = 3, DepartmentID = dept.DepartmentID };
            var content = new byte[] { 1, 2, 3 };
            var mockFile = new Mock<IFormFile>();
            mockFile.Setup(f => f.FileName).Returns("new_image.png");
            mockFile.Setup(f => f.Length).Returns(content.Length);
            mockFile.Setup(f => f.CopyTo(It.IsAny<Stream>()))
                .Callback<Stream>(s => s.Write(content, 0, content.Length));

            // Act
            var result = _controller.Edit(updated, mockFile.Object);

            // Assert
            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
        }

        [Fact]
        public void Edit_Post_InvalidExtension_ReturnsViewWithError()
        {
            // Arrange
            var dept = SeedDepartment();
            var course = new Course { CourseID = 3002, Title = "Bad Ext", Credits = 3, DepartmentID = dept.DepartmentID };
            _context.Courses.Add(course);
            _context.SaveChanges();
            _context.Entry(course).State = EntityState.Detached;

            var updated = new Course { CourseID = 3002, Title = "Bad Ext", Credits = 3, DepartmentID = dept.DepartmentID };
            var mockFile = new Mock<IFormFile>();
            mockFile.Setup(f => f.FileName).Returns("hack.exe");
            mockFile.Setup(f => f.Length).Returns(1024);

            // Act
            var result = _controller.Edit(updated, mockFile.Object) as ViewResult;

            // Assert
            Assert.NotNull(result);
            Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
        }

        [Fact]
        public void Edit_Post_FileTooLarge_ReturnsViewWithError()
        {
            // Arrange
            var dept = SeedDepartment();
            var course = new Course { CourseID = 3003, Title = "Big File", Credits = 3, DepartmentID = dept.DepartmentID };
            _context.Courses.Add(course);
            _context.SaveChanges();
            _context.Entry(course).State = EntityState.Detached;

            var updated = new Course { CourseID = 3003, Title = "Big File", Credits = 3, DepartmentID = dept.DepartmentID };
            var mockFile = new Mock<IFormFile>();
            mockFile.Setup(f => f.FileName).Returns("big.jpg");
            mockFile.Setup(f => f.Length).Returns(10 * 1024 * 1024);

            // Act
            var result = _controller.Edit(updated, mockFile.Object) as ViewResult;

            // Assert
            Assert.NotNull(result);
            Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
        }

        [Fact]
        public void Edit_Post_WithExistingImage_DeletesOldFile()
        {
            // Arrange
            var dept = SeedDepartment();
            var uploadsDir = Path.Combine(_tempDir, "Uploads", "TeachingMaterials");
            Directory.CreateDirectory(uploadsDir);
            var oldFileName = "old_image.jpg";
            var oldFilePath = Path.Combine(uploadsDir, oldFileName);
            File.WriteAllBytes(oldFilePath, new byte[] { 1, 2, 3 });

            var course = new Course
            {
                CourseID = 3004,
                Title = "Replace Image",
                Credits = 3,
                DepartmentID = dept.DepartmentID,
                TeachingMaterialImagePath = $"/Uploads/TeachingMaterials/{oldFileName}"
            };
            _context.Courses.Add(course);
            _context.SaveChanges();
            _context.Entry(course).State = EntityState.Detached;

            var updated = new Course
            {
                CourseID = 3004,
                Title = "Replace Image",
                Credits = 3,
                DepartmentID = dept.DepartmentID,
                TeachingMaterialImagePath = $"/Uploads/TeachingMaterials/{oldFileName}"
            };

            var content = new byte[] { 4, 5, 6 };
            var mockFile = new Mock<IFormFile>();
            mockFile.Setup(f => f.FileName).Returns("new.png");
            mockFile.Setup(f => f.Length).Returns(content.Length);
            mockFile.Setup(f => f.CopyTo(It.IsAny<Stream>()))
                .Callback<Stream>(s => s.Write(content, 0, content.Length));

            // Act
            var result = _controller.Edit(updated, mockFile.Object);

            // Assert
            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
            // Old file should be deleted
            Assert.False(File.Exists(oldFilePath));
        }

        [Fact]
        public void Edit_Post_ModelStateInvalid_ReturnsView()
        {
            // Arrange
            var dept = SeedDepartment();
            var course = new Course { CourseID = 3005, Title = "Invalid", Credits = 3, DepartmentID = dept.DepartmentID };
            _controller.ModelState.AddModelError("Title", "Error");

            // Act
            var result = _controller.Edit(course, null) as ViewResult;

            // Assert
            Assert.NotNull(result);
        }

        [Fact]
        public void DeleteConfirmed_WithImage_DeletesImageFile()
        {
            // Arrange
            var dept = SeedDepartment();
            var uploadsDir = Path.Combine(_tempDir, "Uploads", "TeachingMaterials");
            Directory.CreateDirectory(uploadsDir);
            var fileName = "to_delete.jpg";
            var filePath = Path.Combine(uploadsDir, fileName);
            File.WriteAllBytes(filePath, new byte[] { 1, 2, 3 });

            var course = new Course
            {
                CourseID = 3006,
                Title = "Delete With Image",
                Credits = 3,
                DepartmentID = dept.DepartmentID,
                TeachingMaterialImagePath = $"/Uploads/TeachingMaterials/{fileName}"
            };
            _context.Courses.Add(course);
            _context.SaveChanges();

            // Act
            _controller.DeleteConfirmed(3006);

            // Assert
            Assert.False(File.Exists(filePath));
            Assert.Null(_context.Courses.Find(3006));
        }

        [Fact]
        public void DeleteConfirmed_WithoutImage_Succeeds()
        {
            // Arrange
            var dept = SeedDepartment();
            var course = new Course { CourseID = 3007, Title = "No Image", Credits = 3, DepartmentID = dept.DepartmentID };
            _context.Courses.Add(course);
            _context.SaveChanges();

            // Act
            var result = _controller.DeleteConfirmed(3007);

            // Assert
            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
        }

        [Fact]
        public void Create_Post_ImageUploadException_ReturnsViewWithError()
        {
            // Arrange - Use a path that doesn't exist and make env return null webroot
            var dept = SeedDepartment();
            var course = new Course { CourseID = 3008, Title = "Error Upload", Credits = 3, DepartmentID = dept.DepartmentID };

            var mockFile = new Mock<IFormFile>();
            mockFile.Setup(f => f.FileName).Returns("test.jpg");
            mockFile.Setup(f => f.Length).Returns(100);
            mockFile.Setup(f => f.CopyTo(It.IsAny<Stream>())).Throws(new IOException("Disk full"));

            // Act
            var result = _controller.Create(course, mockFile.Object) as ViewResult;

            // Assert
            Assert.NotNull(result);
            Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
        }
    }
}

using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Services;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.ViewFeatures;
using Moq;
using Xunit;

namespace ContosoUniversity.Tests.Controllers
{
    /// <summary>
    /// Additional tests for NotificationsController to improve coverage.
    /// </summary>
    public class NotificationsControllerEdgeCaseTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly NotificationsController _controller;
        private readonly NotificationService _notificationService;

        public NotificationsControllerEdgeCaseTests()
        {
            _context = TestDbContextFactory.Create();
            _controller = new NotificationsController(_context);
            _controller.TempData = new TempDataDictionary(
                new DefaultHttpContext(),
                Mock.Of<ITempDataProvider>());
            _notificationService = new NotificationService();
        }

        public void Dispose()
        {
            _controller.Dispose();
            _context.Dispose();
            _notificationService.Dispose();
        }

        [Fact]
        public void GetNotifications_WithPendingNotifications_ReturnsNotifications()
        {
            // Arrange - drain any existing then add new ones via the service
            while (_notificationService.ReceiveNotification() != null) { }
            _notificationService.SendNotification("Test", "1", "TestEntity", EntityOperation.CREATE, "Admin");
            _notificationService.SendNotification("Test", "2", "Another", EntityOperation.UPDATE, "User");

            // Act
            var result = _controller.GetNotifications();

            // Assert
            Assert.NotNull(result);
            var json = result.Value;
            var successProp = json.GetType().GetProperty("success");
            Assert.True((bool)successProp.GetValue(json));
            var countProp = json.GetType().GetProperty("count");
            var count = (int)countProp.GetValue(json);
            Assert.True(count >= 1); // At least some notifications returned
        }

        [Fact]
        public void GetNotifications_LimitsTo10()
        {
            // Arrange - drain queue then add 15 notifications
            while (_notificationService.ReceiveNotification() != null) { }
            for (int i = 0; i < 15; i++)
            {
                _notificationService.SendNotification("Bulk", i.ToString(), $"Item {i}", EntityOperation.CREATE);
            }

            // Act
            var result = _controller.GetNotifications();

            // Assert
            var json = result.Value;
            var countProp = json.GetType().GetProperty("count");
            var count = (int)countProp.GetValue(json);
            Assert.True(count <= 10);
        }
    }
}

