using ContosoUniversity.Services;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.ViewFeatures;
using Moq;
using Xunit;

namespace ContosoUniversity.Tests.Controllers
{
    /// <summary>
    /// Additional tests for NotificationsController to improve coverage.
    /// </summary>
    public class NotificationsControllerEdgeCaseTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly NotificationsController _controller;
        private readonly NotificationService _notificationService;

        public NotificationsControllerEdgeCaseTests()
        {
            _context = TestDbContextFactory.Create();
            _controller = new NotificationsController(_context);
            _controller.TempData = new TempDataDictionary(
                new DefaultHttpContext(),
                Mock.Of<ITempDataProvider>());
            _notificationService = new NotificationService();
        }

        public void Dispose()
        {
            _controller.Dispose();
            _context.Dispose();
            _notificationService.Dispose();
        }

        [Fact]
        public void GetNotifications_WithPendingNotifications_ReturnsNotifications()
        {
            // Arrange - drain any existing then add new ones via the service
            while (_notificationService.ReceiveNotification() != null) { }
            _notificationService.SendNotification("Test", "1", "TestEntity", EntityOperation.CREATE, "Admin");
            _notificationService.SendNotification("Test", "2", "Another", EntityOperation.UPDATE, "User");

            // Act
            var result = _controller.GetNotifications();

            // Assert
            Assert.NotNull(result);
            var json = result.Value;
            var successProp = json.GetType().GetProperty("success");
            Assert.True((bool)successProp.GetValue(json));
            var countProp = json.GetType().GetProperty("count");
            var count = (int)countProp.GetValue(json);
            Assert.True(count >= 1); // At least some notifications returned
        }

        [Fact]
        public void GetNotifications_LimitsTo10()
        {
            // Arrange - drain queue then add 15 notifications
            while (_notificationService.ReceiveNotification() != null) { }
            for (int i = 0; i < 15; i++)
            {
                _notificationService.SendNotification("Bulk", i.ToString(), $"Item {i}", EntityOperation.CREATE);
            }

            // Act
            var result = _controller.GetNotifications();

            // Assert
            var json = result.Value;
            var countProp = json.GetType().GetProperty("count");
            var count = (int)countProp.GetValue(json);
            Assert.True(count <= 10);
        }
    }
}

