using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.ViewFeatures;
using Microsoft.EntityFrameworkCore;
using Moq;
using Xunit;

namespace ContosoUniversity.Tests.Controllers
{
    /// <summary>
    /// Additional Instructors tests for UpdateInstructorCourses and Edit POST.
    /// </summary>
    public class InstructorsControllerEdgeCaseTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly InstructorsController _controller;

        public InstructorsControllerEdgeCaseTests()
        {
            _context = TestDbContextFactory.Create();
            _controller = new InstructorsController(_context);
            var httpContext = new DefaultHttpContext();
            _controller.ControllerContext = new ControllerContext
            {
                HttpContext = httpContext
            };
            _controller.TempData = new TempDataDictionary(
                httpContext,
                Mock.Of<ITempDataProvider>());
        }

        public void Dispose()
        {
            _controller.Dispose();
            _context.Dispose();
        }

        private (Instructor instructor, Course course) SeedData()
        {
            var dept = new Department { Name = "Test", Budget = 100000, StartDate = new DateTime(2010, 1, 1) };
            _context.Departments.Add(dept);
            _context.SaveChanges();

            var course = new Course { CourseID = 4001, Title = "TestCourse", Credits = 3, DepartmentID = dept.DepartmentID };
            _context.Courses.Add(course);
            _context.SaveChanges();

            var instructor = new Instructor
            {
                FirstMidName = "Test",
                LastName = "Instructor",
                HireDate = new DateTime(2015, 1, 1),
                OfficeAssignment = new OfficeAssignment { Location = "Room 200" },
                CourseAssignments = new List<CourseAssignment>
                {
                    new CourseAssignment { CourseID = 4001 }
                }
            };
            _context.Instructors.Add(instructor);
            _context.SaveChanges();
            return (instructor, course);
        }

        [Fact]
        public void DeleteConfirmed_InstructorWithOfficeAssignment_RemovesBoth()
        {
            // Arrange
            var (instructor, _) = SeedData();

            // Act
            var result = _controller.DeleteConfirmed(instructor.ID);

            // Assert
            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
            Assert.Null(_context.Instructors.Find(instructor.ID));
            Assert.Null(_context.OfficeAssignments.Find(instructor.ID));
        }

        [Fact]
        public void Create_Post_NullSelectedCourses_CreatesInstructorWithNoCourses()
        {
            // Arrange
            var dept = new Department { Name = "D", Budget = 100, StartDate = DateTime.Now };
            _context.Departments.Add(dept);
            _context.SaveChanges();

            var instructor = new Instructor
            {
                FirstMidName = "No",
                LastName = "Courses",
                HireDate = new DateTime(2023, 1, 1),
                CourseAssignments = new List<CourseAssignment>()
            };

            // Act
            var result = _controller.Create(instructor, null);

            // Assert
            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
            var saved = _context.Instructors
                .Include(i => i.CourseAssignments)
                .First(i => i.LastName == "Courses");
            Assert.Empty(saved.CourseAssignments);
        }
    }
}

